tool_schemas.implementation:
def search_videos(account_id, q, channel_id=None, youtube_channel_id=None, published_after=None, published_before=None, order=None, safe_search=None, video_duration=None, video_definition=None, video_embeddable=None, video_syndicated=None, relevance_language=None, region_code=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None

    def _gen_id(prefix):
        # 18+ chars base32-ish (A-Z2-7); tool patterns indicate [0-9A-Z]
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        h = hashlib.sha256((prefix + _now_iso() + str(time.time_ns())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(alphabet[b % len(alphabet)])
            if len(out) >= 20:
                break
        return f"{prefix}_{''.join(out)}"

    def _reset_quota_if_needed(acct, now_dt):
        # quota_reset_at stored RFC3339; if missing, set to now+24h
        qra = acct.get("quota_reset_at")
        qra_dt = _parse_rfc3339(qra) if isinstance(qra, str) else None
        if qra_dt is None:
            acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()
            acct["quota_daily_used_units"] = int(acct.get("quota_daily_used_units") or 0)
            return
        if now_dt >= qra_dt:
            acct["quota_daily_used_units"] = 0
            acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()

    def _op_row(tool, acct_id, params, page_in=None):
        now = _now_iso()
        return {
            "id": _gen_id("ytop"),
            "account_id": acct_id,
            "tool_name": tool,
            "youtube_endpoint": None,
            "request_params": params,
            "request_body": None,
            "response_body": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "quota_units_charged": 0,
            "latency_ms": None,
            "page_token_in": page_in,
            "page_token_out": None,
            "result_video_ids": None,
            "result_channel_ids": None,
            "result_playlist_ids": None,
            "status": "queued",
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }

    t0 = time.time()
    ops = _load("api_operations.json")
    accounts = _load("accounts.json")
    channels = _load("channels.json")
    videos = _load("videos.json")

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is required and must match ^ytacct_[0-9A-Z]{18,}$")
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q is required and must be a non-empty string")

    if channel_id is not None and (not isinstance(channel_id, str) or not re.match(r"^ytchn_[0-9A-Z]{18,}$", channel_id)):
        return _err("VALIDATION_ERROR", "channel_id must match ^ytchn_[0-9A-Z]{18,}$ when provided")
    if youtube_channel_id is not None and not isinstance(youtube_channel_id, str):
        return _err("VALIDATION_ERROR", "youtube_channel_id must be a string when provided")
    pa = _parse_rfc3339(published_after)
    if published_after is not None and pa is None:
        return _err("VALIDATION_ERROR", "published_after must be RFC3339 date-time")
    pb = _parse_rfc3339(published_before)
    if published_before is not None and pb is None:
        return _err("VALIDATION_ERROR", "published_before must be RFC3339 date-time")
    if pa and pb and pa > pb:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before")

    if limit is None:
        limit = 5
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string when provided")

    enum_order = {"date", "rating", "relevance", "title", "videoCount", "viewCount"}
    enum_safe = {"none", "moderate", "strict"}
    enum_duration = {"any", "short", "medium", "long"}
    enum_definition = {"any", "high", "standard"}
    enum_any_true = {"any", "true"}

    if order is not None and (not isinstance(order, str) or order not in enum_order):
        return _err("VALIDATION_ERROR", "order is invalid")
    if safe_search is not None and (not isinstance(safe_search, str) or safe_search not in enum_safe):
        return _err("VALIDATION_ERROR", "safe_search is invalid")
    if video_duration is not None and (not isinstance(video_duration, str) or video_duration not in enum_duration):
        return _err("VALIDATION_ERROR", "video_duration is invalid")
    if video_definition is not None and (not isinstance(video_definition, str) or video_definition not in enum_definition):
        return _err("VALIDATION_ERROR", "video_definition is invalid")
    if video_embeddable is not None and (not isinstance(video_embeddable, str) or video_embeddable not in enum_any_true):
        return _err("VALIDATION_ERROR", "video_embeddable is invalid")
    if video_syndicated is not None and (not isinstance(video_syndicated, str) or video_syndicated not in enum_any_true):
        return _err("VALIDATION_ERROR", "video_syndicated is invalid")
    if relevance_language is not None and not isinstance(relevance_language, str):
        return _err("VALIDATION_ERROR", "relevance_language must be a string when provided")
    if region_code is not None and not isinstance(region_code, str):
        return _err("VALIDATION_ERROR", "region_code must be a string when provided")

    # Resolve account and ensure active
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        return _err("NOT_FOUND", "account not found", account_id=account_id)
    if acct.get("status") != "active":
        # Authenticated tool behavior for this server: account must be active
        return _err("UNAUTHORIZED", "account is not active", account_id=account_id, status=acct.get("status"))

    # Resolve channel filter (internal or youtube)
    channel_row = None
    if channel_id is not None:
        channel_row = next((c for c in channels if c.get("id") == channel_id), None)
        if channel_row is None:
            return _err("NOT_FOUND", "channel_id not found", channel_id=channel_id)
    if youtube_channel_id is not None:
        ch2 = next((c for c in channels if c.get("youtube_channel_id") == youtube_channel_id), None)
        if ch2 is None:
            # create stub channel row as "unknown"
            now = _now_iso()
            ch2 = {
                "id": _gen_id("ytchn"),
                "youtube_channel_id": youtube_channel_id,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now,
                "status": "unknown",
                "created_at": now,
                "updated_at": now,
            }
            channels.append(ch2)
        if channel_row is not None and channel_row.get("id") != ch2.get("id"):
            return _err("CONFLICT", "channel_id and youtube_channel_id refer to different cached channels",
                        channel_id=channel_id, youtube_channel_id=youtube_channel_id)
        channel_row = ch2

    # Create operation row (queued)
    req_params = {
        "account_id": account_id,
        "q": q,
        "channel_id": channel_id,
        "youtube_channel_id": youtube_channel_id,
        "published_after": published_after,
        "published_before": published_before,
        "order": order,
        "safe_search": safe_search,
        "video_duration": video_duration,
        "video_definition": video_definition,
        "video_embeddable": video_embeddable,
        "video_syndicated": video_syndicated,
        "relevance_language": relevance_language,
        "region_code": region_code,
        "limit": limit,
        "page_token": page_token,
    }
    op = _op_row("search_videos", account_id, req_params, page_in=page_token)
    ops.append(op)
    _save("api_operations.json", ops)

    # Transition queued -> running
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    op["status"] = "running"
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]
    _save("api_operations.json", ops)

    # Quota cost (approx YouTube search.list)
    quota_cost = 100
    op["quota_units_charged"] = quota_cost
    op["youtube_endpoint"] = "search.list"

    # Enforce quota
    _reset_quota_if_needed(acct, now_dt)
    limit_units = int(acct.get("quota_daily_limit_units") or 0)
    used_units = int(acct.get("quota_daily_used_units") or 0)
    if limit_units > 0 and (used_units + quota_cost) > limit_units:
        op["status"] = "failed"
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
        op["http_status"] = 403
        op["error_code"] = "quotaExceeded"
        op["error_message"] = "Daily quota limit exceeded for account"
        op["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", ops)
        acct["updated_at"] = _now_iso()
        _save("accounts.json", accounts)
        return _err("QUOTA_EXCEEDED", "Daily quota limit exceeded", error_code="quotaExceeded")

    # Charge quota + last_used_at
    acct["quota_daily_used_units"] = used_units + quota_cost
    acct["last_used_at"] = _now_iso()
    acct["updated_at"] = acct["last_used_at"]
    _save("accounts.json", accounts)

    # Offline server behavior: search over cached videos, matching q against title/description
    qlow = q.strip().lower()
    def _match_text(v):
        t = (v.get("title") or "").lower()
        d = (v.get("description") or "").lower()
        return qlow in t or qlow in d

    # Filter base set: active/unknown videos (exclude deleted unless explicitly matched? We'll exclude deleted)
    cand = [v for v in videos if v.get("status") in ("active", "unknown")]

    if channel_row is not None:
        cand = [v for v in cand if v.get("channel_id") == channel_row.get("id")]

    # published_after/before filter: use published_at if present
    if pa:
        cand = [v for v in cand if (v.get("published_at") and _parse_rfc3339(v.get("published_at")) and _parse_rfc3339(v.get("published_at")) >= pa)]
    if pb:
        cand = [v for v in cand if (v.get("published_at") and _parse_rfc3339(v.get("published_at")) and _parse_rfc3339(v.get("published_at")) <= pb)]

    # Text match
    cand = [v for v in cand if _match_text(v)]

    # Sort
    def _safe_int(x):
        try:
            return int(x)
        except Exception:
            return 0

    if order in (None, "relevance"):
        # crude relevance: title hit first then description
        def _rel(v):
            t = (v.get("title") or "").lower()
            d = (v.get("description") or "").lower()
            return (0 if qlow in t else 1, 0 if qlow in d else 1, (v.get("published_at") or ""))
        cand.sort(key=_rel)
    elif order == "date":
        cand.sort(key=lambda v: (v.get("published_at") or ""), reverse=True)
    elif order == "title":
        cand.sort(key=lambda v: ((v.get("title") or "").lower(), v.get("youtube_video_id") or ""))
    elif order == "viewCount":
        cand.sort(key=lambda v: _safe_int(v.get("view_count")), reverse=True)
    elif order == "rating":
        cand.sort(key=lambda v: _safe_int(v.get("like_count")), reverse=True)
    elif order == "videoCount":
        # Not meaningful at video level; approximate by channel's video_count if available
        ch_index = {c.get("id"): c for c in channels}
        cand.sort(key=lambda v: _safe_int((ch_index.get(v.get("channel_id")) or {}).get("video_count")), reverse=True)

    # Pagination: opaque token encodes offset with hash
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"==").decode("utf-8")
            parts = raw.split(":")
            if len(parts) == 2 and parts[0] == "off":
                offset = int(parts[1])
                if offset < 0:
                    offset = 0
        except Exception:
            # invalid tokens are validation errors
            op["status"] = "failed"
            op["finished_at"] = _now_iso()
            op["updated_at"] = op["finished_at"]
            op["http_status"] = 400
            op["error_code"] = "invalidArgument"
            op["error_message"] = "Invalid page_token"
            op["latency_ms"] = int((time.time() - t0) * 1000)
            _save("api_operations.json", ops)
            return _err("VALIDATION_ERROR", "page_token is invalid")

    total = len(cand)
    page = cand[offset:offset + limit]
    next_offset = offset + len(page)
    next_token = None
    if next_offset < total:
        next_token = base64.urlsafe_b64encode(f"off:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Persist upserts: channels referenced by results (already in cache) and videos touched (refresh fetched_at)
    now = _now_iso()
    ch_by_id = {c.get("id"): c for c in channels}
    result_video_ids = []
    result_channel_ids = []

    for v in page:
        # upsert video by youtube_video_id (ensure uniqueness)
        yvid = v.get("youtube_video_id")
        if not isinstance(yvid, str) or not yvid:
            continue
        existing = next((vv for vv in videos if vv.get("youtube_video_id") == yvid), None)
        if existing is None:
            # Should not happen since v is from videos, but keep safe
            nv = dict(v)
            nv["id"] = _gen_id("ytvid")
            nv["created_at"] = now
            nv["updated_at"] = now
            nv["fetched_at"] = now
            videos.append(nv)
            existing = nv
        else:
            existing["fetched_at"] = now
            existing["updated_at"] = now
        result_video_ids.append(yvid)

        ch = ch_by_id.get(existing.get("channel_id"))
        if ch and ch.get("youtube_channel_id"):
            result_channel_ids.append(ch.get("youtube_channel_id"))

    # De-dup
    result_video_ids = list(dict.fromkeys(result_video_ids))
    result_channel_ids = list(dict.fromkeys([x for x in result_channel_ids if x]))

    _save("channels.json", channels)
    _save("videos.json", videos)

    # Finish operation
    op["status"] = "succeeded"
    op["finished_at"] = _now_iso()
    op["updated_at"] = op["finished_at"]
    op["http_status"] = 200
    op["page_token_out"] = next_token
    op["result_video_ids"] = result_video_ids
    op["result_channel_ids"] = result_channel_ids
    op["response_body"] = {"total_results": total, "returned": len(page)}
    op["latency_ms"] = int((time.time() - t0) * 1000)
    _save("api_operations.json", ops)

    # Return envelope
    items = []
    for v in page:
        ch = ch_by_id.get(v.get("channel_id")) or {}
        items.append({
            "youtube_video_id": v.get("youtube_video_id"),
            "title": v.get("title"),
            "description": v.get("description"),
            "published_at": v.get("published_at"),
            "privacy_status": v.get("privacy_status"),
            "upload_status": v.get("upload_status"),
            "channel": {
                "youtube_channel_id": ch.get("youtube_channel_id"),
                "title": ch.get("title"),
            }
        })

    return {
        "operation_id": op["id"],
        "items": items,
        "next_page_token": next_token,
        "page_info": {
            "total_results": total,
            "results_per_page": limit,
            "has_more": next_token is not None
        }
    }

def get_channel_info(account_id, channel_ids, include_parts=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        h = hashlib.sha256((prefix + _now_iso() + str(time.time_ns())).encode("utf-8")).digest()
        out = []
        for b in h:
            out.append(alphabet[b % len(alphabet)])
            if len(out) >= 20:
                break
        return f"{prefix}_{''.join(out)}"

    def _reset_quota_if_needed(acct, now_dt):
        qra = acct.get("quota_reset_at")
        qra_dt = _parse_rfc3339(qra) if isinstance(qra, str) else None
        if qra_dt is None:
            acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()
            acct["quota_daily_used_units"] = int(acct.get("quota_daily_used_units") or 0)
            return
        if now_dt >= qra_dt:
            acct["quota_daily_used_units"] = 0
            acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat()

    def _op_row(tool, acct_id, params):
        now = _now_iso()
        return {
            "id": _gen_id("ytop"),
            "account_id": acct_id,
            "tool_name": tool,
            "youtube_endpoint": None,
            "request_params": params,
            "request_body": None,
            "response_body": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "quota_units_charged": 0,
            "latency_ms": None,
            "page_token_in": None,
            "page_token_out": None,
            "result_video_ids": None,
            "result_channel_ids": None,
            "result_playlist_ids": None,
            "status": "queued",
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }

    t0 = time.time()
    ops = _load("api_operations.json")
    accounts = _load("accounts.json")
    channels = _load("channels.json")

    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is required and must match ^ytacct_[0-9A-Z]{18,}$")
    if not isinstance(channel_ids, list) or not (1 <= len(channel_ids) <= 50) or not all(isinstance(x, str) and x for x in channel_ids):
        return _err("VALIDATION_ERROR", "channel_ids must be an array of 1..50 non-empty strings")
    if include_parts is not None:
        if not isinstance(include_parts, list) or len(include_parts) < 1:
            return _err("VALIDATION_ERROR", "include_parts must be a non-empty array when provided")
        allowed = {"snippet", "contentDetails", "statistics", "status"}
        for p in include_parts:
            if not isinstance(p, str) or p not in allowed:
                return _err("VALIDATION_ERROR", "include_parts contains invalid value")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        return _err("NOT_FOUND", "account not found", account_id=account_id)
    if acct.get("status") != "active":
        return _err("UNAUTHORIZED", "account is not active", account_id=account_id, status=acct.get("status"))

    req_params = {"account_id": account_id, "channel_ids": channel_ids, "include_parts": include_parts}
    op = _op_row("get_channel_info", account_id, req_params)
    ops.append(op)
    _save("api_operations.json", ops)

    op["status"] = "running"
    op["started_at"] = _now_iso()
    op["updated_at"] = op["started_at"]
    _save("api_operations.json", ops)

    quota_cost = 1  # channels.list
    op["quota_units_charged"] = quota_cost
    op["youtube_endpoint"] = "channels.list"

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    _reset_quota_if_needed(acct, now_dt)
    limit_units = int(acct.get("quota_daily_limit_units") or 0)
    used_units = int(acct.get("quota_daily_used_units") or 0)
    if limit_units > 0 and (used_units + quota_cost) > limit_units:
        op["status"] = "failed"
        op["finished_at"] = _now_iso()
        op["updated_at"] = op["finished_at"]
        op["http_status"] = 403
        op["error_code"] = "quotaExceeded"
        op["error_message"] = "Daily quota limit exceeded for account"
        op["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", ops)
        acct["updated_at"] = _now_iso()
        _save("accounts.json", accounts)
        return _err("QUOTA_EXCEEDED", "Daily quota limit exceeded", error_code="quotaExceeded")

    acct["quota_daily_used_units"] = used_units + quota_cost
    acct["last_used_at"] = _now_iso()
    acct["updated_at"] = acct["last_used_at"]
    _save("accounts.json", accounts)

    # Offline behavior: return cached channels; if missing, create/transition stub to deleted
    now = _now_iso()
    returned = []
    result_channel_ids = []
    for ychid in channel_ids:
        ch = next((c for c in channels if c.get("youtube_channel_id") == ychid), None)
        if ch is None:
            ch = {
                "id": _gen_id("ytchn"),
                "youtube_channel_id": ychid,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now,
                "status": "deleted",
                "created_at": now,
                "updated_at": now,
            }
            channels.append(ch)
        else:
            ch["fetched_at"] = now
            ch["updated_at"] = now

        returned.append({
            "youtube_channel_id": ch.get("youtube_channel_id"),
            "title": ch.get("title"),
            "description": ch.get("description"),
            "custom_url": ch.get("custom_url"),
            "published_at": ch.get("published_at"),
            "country": ch.get("country"),
            "statistics": {
                "subscriber_count": ch.get("subscriber_count"),
                "video_count": ch.get("video_count"),
                "view_count": ch.get("view_count"),
            },
            "status": ch.get("status"),
        })
        result_channel_ids.append(ch.get("youtube_channel_id"))

    _save("channels.json", channels)

    op["status"] = "succeeded"
    op["finished_at"] = _now_iso()
    op["updated_at"] = op["finished_at"]
    op["http_status"] = 200
    op["result_channel_ids"] = list(dict.fromkeys([x for x in result_channel_ids if x]))
    op["response_body"] = {"requested": len(channel_ids), "returned": len(returned)}
    op["latency_ms"] = int((time.time() - t0) * 1000)
    _save("api_operations.json", ops)

    return {"operation_id": op["id"], "items": returned}

def list_channel_videos(account_id, channel_id=None, youtube_channel_id=None, order=None, published_after=None, published_before=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, time, secrets, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    # ---- helpers ----
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize(v)
            return out
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj]
        return obj

    def _b64_json(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64_json_load(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _quota_reset_if_needed(acct):
        # If quota_reset_at is in past, reset usage and push reset forward by 1 day until it's in future.
        try:
            qra = acct.get("quota_reset_at")
            if not isinstance(qra, str):
                return
            ss = qra
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            reset_dt = datetime.datetime.fromisoformat(ss)
            if reset_dt.tzinfo is None:
                reset_dt = reset_dt.replace(tzinfo=datetime.timezone.utc)
            reset_dt = reset_dt.astimezone(datetime.timezone.utc)
        except Exception:
            return
        if reset_dt > now_dt:
            return
        # advance by days
        delta_days = 1
        while reset_dt <= now_dt and delta_days < 370:
            reset_dt = reset_dt + datetime.timedelta(days=1)
            delta_days += 1
        acct["quota_daily_used_units"] = 0
        acct["quota_reset_at"] = reset_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _find_account(accounts, account_id_val):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id_val:
                return a
        return None

    # ---- validate inputs (relax limit max per audit: accept large numbers, clamp to 50 like YouTube page size) ----
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id must be a string matching ^ytacct_[0-9A-Z]{18,}$")

    if channel_id is None and youtube_channel_id is None:
        return _err("VALIDATION_ERROR", "One of channel_id or youtube_channel_id is required")

    if channel_id is not None:
        if not isinstance(channel_id, str) or not re.match(r"^ytchn_[0-9A-Z]{18,}$", channel_id):
            return _err("VALIDATION_ERROR", "channel_id must be a string matching ^ytchn_[0-9A-Z]{18,}$")
    if youtube_channel_id is not None:
        if not isinstance(youtube_channel_id, str) or not youtube_channel_id.strip():
            return _err("VALIDATION_ERROR", "youtube_channel_id must be a non-empty string when provided")

    if order is not None:
        if not isinstance(order, str):
            return _err("VALIDATION_ERROR", "order must be a string when provided")
        if order not in ("date", "rating", "relevance", "title", "videoCount", "viewCount"):
            return _err("VALIDATION_ERROR", "order must be one of: date, rating, relevance, title, videoCount, viewCount")

    pa_dt = _parse_rfc3339(published_after)
    if published_after is not None and pa_dt is None:
        return _err("VALIDATION_ERROR", "published_after must be RFC3339 date-time when provided")
    pb_dt = _parse_rfc3339(published_before)
    if published_before is not None and pb_dt is None:
        return _err("VALIDATION_ERROR", "published_before must be RFC3339 date-time when provided")
    if pa_dt and pb_dt and pa_dt > pb_dt:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before")

    if limit is None:
        req_limit = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer when provided")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be >= 1")
        # relax: if > 50, clamp (server can accept but YouTube page size is 50)
        req_limit = 50 if limit > 50 else limit

    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")

    accounts = _load("accounts.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    api_ops = _load("api_operations.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(channels, list): channels = []
    if not isinstance(videos, list): videos = []
    if not isinstance(api_ops, list): api_ops = []

    acct = _find_account(accounts, account_id)
    if not acct or acct.get("status") != "active":
        # list_channel_videos is not listed as "authenticated-only" in business rules; but tool requires account_id.
        # Treat non-existent/inactive as UNAUTHORIZED for this call context.
        # Still must record an api_operation row.
        op_id = _new_id("ytop")
        op_row = {
            "id": op_id,
            "account_id": acct.get("id") if isinstance(acct, dict) else None,
            "tool_name": "list_channel_videos",
            "youtube_endpoint": "search.list",
            "request_params": _sanitize({
                "account_id": account_id,
                "channel_id": channel_id,
                "youtube_channel_id": youtube_channel_id,
                "order": order,
                "published_after": published_after,
                "published_before": published_before,
                "limit": req_limit,
                "page_token": page_token
            }),
            "request_body": None,
            "response_body": None,
            "http_status": 401,
            "error_code": "authError",
            "error_message": "Account not found or not active for this request.",
            "quota_units_charged": 0,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "page_token_in": page_token,
            "page_token_out": None,
            "result_video_ids": [],
            "result_channel_ids": [],
            "result_playlist_ids": None,
            "status": "failed",
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        api_ops.append(op_row)
        _save("api_operations.json", api_ops)
        return _err("UNAUTHORIZED", "Account not found or not active")

    # quota reset check
    _quota_reset_if_needed(acct)

    # create operation row queued -> running
    op_id = _new_id("ytop")
    op_row = {
        "id": op_id,
        "account_id": acct.get("id"),
        "tool_name": "list_channel_videos",
        "youtube_endpoint": "search.list",
        "request_params": _sanitize({
            "account_id": account_id,
            "channel_id": channel_id,
            "youtube_channel_id": youtube_channel_id,
            "order": order,
            "published_after": published_after,
            "published_before": published_before,
            "limit": req_limit,
            "page_token": page_token
        }),
        "request_body": None,
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 100,  # approximate YouTube search.list cost
        "latency_ms": None,
        "page_token_in": page_token,
        "page_token_out": None,
        "result_video_ids": [],
        "result_channel_ids": [],
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    api_ops.append(op_row)

    # transition to running
    op_row["status"] = "running"
    op_row["started_at"] = now_iso
    op_row["updated_at"] = now_iso

    # enforce quota
    qlimit = acct.get("quota_daily_limit_units")
    qused = acct.get("quota_daily_used_units")
    try:
        qlimit_i = int(qlimit) if qlimit is not None else 0
    except Exception:
        qlimit_i = 0
    try:
        qused_i = int(qused) if qused is not None else 0
    except Exception:
        qused_i = 0
    if qlimit_i > 0 and (qused_i + int(op_row["quota_units_charged"])) > qlimit_i:
        op_row["status"] = "failed"
        op_row["http_status"] = 403
        op_row["error_code"] = "quotaExceeded"
        op_row["error_message"] = "The request cannot be completed because you have exceeded your quota."
        op_row["finished_at"] = now_iso
        op_row["updated_at"] = now_iso
        op_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        acct["last_used_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("api_operations.json", api_ops)
        _save("accounts.json", accounts)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this account", error_code="quotaExceeded")

    # resolve / upsert channel
    ch = None
    if channel_id is not None:
        for r in channels:
            if isinstance(r, dict) and r.get("id") == channel_id:
                ch = r
                break
        if not ch:
            # create stub row as "unknown" (allowed transition unknown->active/deleted later)
            ch = {
                "id": channel_id,
                "youtube_channel_id": youtube_channel_id if youtube_channel_id else ("UC" + _new_id("stub")[5:]),
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now_iso,
                "status": "unknown",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            channels.append(ch)
    else:
        # find by youtube_channel_id, else create stub
        for r in channels:
            if isinstance(r, dict) and r.get("youtube_channel_id") == youtube_channel_id:
                ch = r
                break
        if not ch:
            ch = {
                "id": _new_id("ytchn"),
                "youtube_channel_id": youtube_channel_id,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now_iso,
                "status": "unknown",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            channels.append(ch)

    # emulate "list" from cache: return cached videos for channel, apply filters and pagination
    def _dt_from_row(vrow):
        dt = None
        if isinstance(vrow.get("published_at"), str):
            dt = _parse_rfc3339(vrow.get("published_at"))
        if dt is None and isinstance(vrow.get("publish_at"), str):
            dt = _parse_rfc3339(vrow.get("publish_at"))
        return dt

    channel_videos = []
    for v in videos:
        if not isinstance(v, dict):
            continue
        if v.get("channel_id") != ch.get("id"):
            continue
        if v.get("status") == "deleted":
            continue
        dt = _dt_from_row(v)
        if pa_dt and dt and dt < pa_dt:
            continue
        if pb_dt and dt and dt > pb_dt:
            continue
        channel_videos.append(v)

    # ordering (best-effort with cached fields)
    if order in (None, "date"):
        channel_videos.sort(key=lambda r: (_dt_from_row(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    elif order == "title":
        channel_videos.sort(key=lambda r: (r.get("title") or "").lower())
    elif order == "viewCount":
        channel_videos.sort(key=lambda r: (r.get("view_count") if isinstance(r.get("view_count"), int) else -1), reverse=True)
    elif order == "rating":
        # no rating field cached; fall back to like_count
        channel_videos.sort(key=lambda r: (r.get("like_count") if isinstance(r.get("like_count"), int) else -1), reverse=True)
    elif order == "relevance":
        # no relevance scoring; stable by date desc
        channel_videos.sort(key=lambda r: (_dt_from_row(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    elif order == "videoCount":
        # not meaningful for video list; keep stable
        pass

    # pagination token (server-side cursor)
    start = 0
    token_payload = _b64_json_load(page_token) if page_token else None
    if isinstance(token_payload, dict) and token_payload.get("tool") == "list_channel_videos" and token_payload.get("channel_id") == ch.get("id"):
        try:
            start = int(token_payload.get("offset", 0))
            if start < 0:
                start = 0
        except Exception:
            start = 0
    else:
        # accept arbitrary opaque tokens from prior YouTube calls but don't error; treat as start=0
        start = 0

    page = channel_videos[start:start + req_limit]
    next_offset = start + len(page)
    next_token = None
    if next_offset < len(channel_videos):
        next_token = _b64_json({"tool": "list_channel_videos", "channel_id": ch.get("id"), "offset": next_offset})

    # upsert fetched_at on returned videos (they were "observed" now)
    returned_ids = []
    for v in page:
        if not isinstance(v, dict):
            continue
        v["fetched_at"] = now_iso
        v["updated_at"] = now_iso
        if isinstance(v.get("youtube_video_id"), str):
            returned_ids.append(v.get("youtube_video_id"))

    # record results
    op_row["status"] = "succeeded"
    op_row["http_status"] = 200
    op_row["response_body"] = _sanitize({
        "items": [{"youtube_video_id": v.get("youtube_video_id")} for v in page if isinstance(v, dict)],
        "total_cached_for_channel": len(channel_videos)
    })
    op_row["page_token_out"] = next_token
    op_row["result_video_ids"] = returned_ids
    op_row["result_channel_ids"] = [ch.get("youtube_channel_id")] if isinstance(ch.get("youtube_channel_id"), str) else []
    op_row["finished_at"] = now_iso
    op_row["updated_at"] = now_iso
    op_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))

    # charge quota and update account last_used_at
    acct["quota_daily_used_units"] = qused_i + int(op_row["quota_units_charged"])
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso

    _save("videos.json", videos)
    _save("channels.json", channels)
    _save("accounts.json", accounts)
    _save("api_operations.json", api_ops)

    return {
        "items": page,
        "channel": ch,
        "page_token": next_token,
        "limit": req_limit,
        "total_cached": len(channel_videos),
        "has_more": bool(next_token),
        "api_operation": op_row
    }

def upload_video(account_id, snippet, youtube_channel_id=None, media_url=None, media_path=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize(v)
            return out
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj]
        return obj

    def _finalize(api_ops, op_id, status_val, http_status=None, error_code=None, error_message=None, response_body=None, result_video_ids=None, result_channel_ids=None):
        for r in api_ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r["status"] = status_val
                r["updated_at"] = now_iso
                if r.get("started_at") and status_val in ("succeeded", "failed", "cancelled"):
                    r["finished_at"] = now_iso
                if http_status is not None:
                    r["http_status"] = int(http_status)
                r["error_code"] = error_code
                r["error_message"] = error_message
                if response_body is not None:
                    r["response_body"] = _sanitize(response_body)
                if result_video_ids is not None:
                    r["result_video_ids"] = result_video_ids
                if result_channel_ids is not None:
                    r["result_channel_ids"] = result_channel_ids
                break
        _save("api_operations.json", api_ops)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid")

    if not isinstance(snippet, dict):
        return _err("VALIDATION_ERROR", "snippet must be an object")
    if not isinstance(snippet.get("title"), str) or not snippet.get("title").strip():
        return _err("VALIDATION_ERROR", "snippet.title is required")

    # Accept both media_url and media_path if caller provides both; require at least one.
    if (media_url is None or (isinstance(media_url, str) and not media_url.strip())) and (media_path is None or (isinstance(media_path, str) and not media_path.strip())):
        return _err("VALIDATION_ERROR", "At least one of media_url or media_path must be provided")
    if media_url is not None and (not isinstance(media_url, str) or not media_url.strip()):
        return _err("VALIDATION_ERROR", "media_url must be a non-empty string when provided")
    if media_path is not None and (not isinstance(media_path, str) or not media_path.strip()):
        return _err("VALIDATION_ERROR", "media_path must be a non-empty string when provided")

    if youtube_channel_id is not None and (not isinstance(youtube_channel_id, str) or not youtube_channel_id.strip()):
        return _err("VALIDATION_ERROR", "youtube_channel_id must be a non-empty string when provided")

    if "tags" in snippet and snippet["tags"] is not None:
        if not isinstance(snippet["tags"], list) or any(not isinstance(t, str) for t in snippet["tags"]):
            return _err("VALIDATION_ERROR", "snippet.tags must be an array of strings when provided")
    if "category_id" in snippet and snippet["category_id"] is not None and not isinstance(snippet["category_id"], int):
        return _err("VALIDATION_ERROR", "snippet.category_id must be an integer when provided")
    if "default_language" in snippet and snippet["default_language"] is not None and not isinstance(snippet["default_language"], str):
        return _err("VALIDATION_ERROR", "snippet.default_language must be a string when provided")

    privacy_status = "private"
    publish_at = None
    if status is not None:
        if not isinstance(status, dict):
            return _err("VALIDATION_ERROR", "status must be an object when provided")
        if "privacy_status" in status and status["privacy_status"] is not None:
            if status["privacy_status"] not in ("public", "private", "unlisted"):
                return _err("VALIDATION_ERROR", "status.privacy_status must be one of: public, private, unlisted")
            privacy_status = status["privacy_status"]
        if "publish_at" in status and status["publish_at"] is not None:
            publish_at_dt = _parse_rfc3339(status["publish_at"])
            if publish_at_dt is None:
                return _err("VALIDATION_ERROR", "status.publish_at must be RFC3339 date-time when provided")
            publish_at = status["publish_at"]

    accounts = _load("accounts.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    api_ops = _load("api_operations.json")

    if not isinstance(accounts, list): accounts = []
    if not isinstance(channels, list): channels = []
    if not isinstance(videos, list): videos = []
    if not isinstance(api_ops, list): api_ops = []

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        return _err("UNAUTHORIZED", "Account is not active", account_id=account_id)

    # Determine target youtube channel id
    target_ycid = youtube_channel_id or acct.get("default_channel_id")
    if not isinstance(target_ycid, str) or not target_ycid.strip():
        return _err("VALIDATION_ERROR", "youtube_channel_id omitted and account has no default_channel_id")

    # Find or create channel row
    ch = None
    for c in channels:
        if isinstance(c, dict) and c.get("youtube_channel_id") == target_ycid:
            ch = c
            break
    if ch is None:
        ch = {
            "id": _new_id("ytchn"),
            "youtube_channel_id": target_ycid,
            "title": None,
            "description": None,
            "custom_url": None,
            "published_at": None,
            "country": None,
            "subscriber_count": None,
            "video_count": None,
            "view_count": None,
            "etag": None,
            "fetched_at": now_iso,
