def update_video(account_id, youtube_video_id, snippet=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize(v)
            return out
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj]
        return obj

    def _finalize(api_ops, op_id, status_val, http_status=None, error_code=None, error_message=None, response_body=None, result_video_ids=None):
        for r in api_ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r["status"] = status_val
                r["updated_at"] = now_iso
                if r.get("started_at") and status_val in ("succeeded", "failed", "cancelled"):
                    r["finished_at"] = now_iso
                if http_status is not None:
                    r["http_status"] = int(http_status)
                r["error_code"] = error_code
                r["error_message"] = error_message
                if response_body is not None:
                    r["response_body"] = _sanitize(response_body)
                if result_video_ids is not None:
                    r["result_video_ids"] = result_video_ids
                break
        _save("api_operations.json", api_ops)

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if not isinstance(youtube_video_id, str) or not youtube_video_id.strip():
        return _err("VALIDATION_ERROR", "youtube_video_id must be a non-empty string")

    if snippet is not None and not isinstance(snippet, dict):
        return _err("VALIDATION_ERROR", "snippet must be an object when provided")
    if status is not None and not isinstance(status, dict):
        return _err("VALIDATION_ERROR", "status must be an object when provided")

    if snippet is not None and "tags" in snippet and snippet["tags"] is not None:
        if not isinstance(snippet["tags"], list) or any(not isinstance(t, str) for t in snippet["tags"]):
            return _err("VALIDATION_ERROR", "snippet.tags must be an array of strings when provided")
    if snippet is not None and "category_id" in snippet and snippet["category_id"] is not None and not isinstance(snippet["category_id"], int):
        return _err("VALIDATION_ERROR", "snippet.category_id must be an integer when provided")
    if snippet is not None and "default_language" in snippet and snippet["default_language"] is not None and not isinstance(snippet["default_language"], str):
        return _err("VALIDATION_ERROR", "snippet.default_language must be a string when provided")

    new_privacy = None
    new_publish_at = None
    if status is not None:
        if "privacy_status" in status and status["privacy_status"] is not None:
            if status["privacy_status"] not in ("public", "private", "unlisted"):
                return _err("VALIDATION_ERROR", "status.privacy_status must be one of: public, private, unlisted")
            new_privacy = status["privacy_status"]
        if "publish_at" in status and status["publish_at"] is not None:
            if _parse_rfc3339(status["publish_at"]) is None:
                return _err("VALIDATION_ERROR", "status.publish_at must be RFC3339 date-time when provided")
            new_publish_at = status["publish_at"]

    accounts = _load("accounts.json")
    videos = _load("videos.json")
    api_ops = _load("api_operations.json")

    if not isinstance(accounts, list): accounts = []
    if not isinstance(videos, list): videos = []
    if not isinstance(api_ops, list): api_ops = []

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        return _err("UNAUTHORIZED", "Account is not active", account_id=account_id)

    # Create api_operation row
    op_id = _new_id("ytop")
    op_row = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "update_video",
        "youtube_endpoint": "videos.update",
        "request_params": _sanitize({"account_id": account_id, "youtube_video_id": youtube_video_id}),
        "request_body": _sanitize({"snippet": snippet, "status": status}),
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 50,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": None,
        "result_channel_ids": None,
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_ops.append(op_row)
    _save("api_operations.json", api_ops)

    op_row["status"] = "running"
    op_row["started_at"] = now_iso
    op_row["updated_at"] = now_iso
    _save("api_operations.json", api_ops)

    # Quota reset / enforce
    def _parse_quota_dt(s):
        dt = _parse_rfc3339(s)
        if dt is None:
            return None
        if dt.tzinfo is None:
            return dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    qra = _parse_quota_dt(acct.get("quota_reset_at")) if isinstance(acct, dict) else None
    if qra is None:
        acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat().replace("+00:00", "Z")
        acct["quota_daily_used_units"] = int(acct.get("quota_daily_used_units") or 0)
    else:
        if now_dt >= qra:
            acct["quota_daily_used_units"] = 0
            acct["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).isoformat().replace("+00:00", "Z")

    quota_cost = int(op_row.get("quota_units_charged") or 0)
    limit_units = int(acct.get("quota_daily_limit_units") or 0)
    used_units = int(acct.get("quota_daily_used_units") or 0)
    if limit_units > 0 and used_units + quota_cost > limit_units:
        _finalize(api_ops, op_id, "failed", http_status=403, error_code="quotaExceeded",
                  error_message="The request cannot be completed because you have exceeded your quota.")
        acct["last_used_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("accounts.json", accounts)
        return _err("QUOTA_EXCEEDED", "Quota exceeded", error_code="quotaExceeded")

    # Find video row by natural id
    vrow = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == youtube_video_id:
            vrow = v
            break
    if vrow is None:
        _finalize(api_ops, op_id, "failed", http_status=404, error_code="notFound", error_message="Video not found or has been removed.")
        acct["quota_daily_used_units"] = used_units + quota_cost
        acct["last_used_at"] = now_iso
        acct["updated_at"] = now_iso
        _save("accounts.json", accounts)
        return _err("NOT_FOUND", "Video not found", youtube_video_id=youtube_video_id)

    # Apply updates to cached fields only (business rule)
    if snippet:
        for k in ("title", "description", "tags", "category_id", "default_language"):
            if k in snippet:
                vrow[k] = snippet[k]
    if new_privacy is not None:
        vrow["privacy_status"] = new_privacy
        # if made public and no schedule, set published_at
        if new_privacy == "public" and (new_publish_at is None):
            if not vrow.get("published_at"):
                vrow["published_at"] = now_iso
    if "publish_at" in (status or {}):
        # Server allows scheduling by storing publish_at; if caller sets null, clear it.
        vrow["publish_at"] = new_publish_at

    vrow["fetched_at"] = now_iso
    vrow["updated_at"] = now_iso
    _save("videos.json", videos)

    acct["quota_daily_used_units"] = used_units + quota_cost
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    _finalize(api_ops, op_id, "succeeded", http_status=200, response_body={"id": youtube_video_id}, result_video_ids=[youtube_video_id])

    latency_ms = int((time.time() - t0) * 1000)
    for r in api_ops:
        if isinstance(r, dict) and r.get("id") == op_id:
            r["latency_ms"] = latency_ms
            r["updated_at"] = now_iso
            break
    _save("api_operations.json", api_ops)

