                ss = ss[:-1] + "+00:00"
            reset_dt = datetime.datetime.fromisoformat(ss)
            if reset_dt.tzinfo is None:
                reset_dt = reset_dt.replace(tzinfo=datetime.timezone.utc)
            reset_dt = reset_dt.astimezone(datetime.timezone.utc)
        except Exception:
            return
        if reset_dt > now_dt:
            return
        delta_days = 1
        while reset_dt <= now_dt and delta_days < 370:
            reset_dt = reset_dt + datetime.timedelta(days=1)
            delta_days += 1
