                "fetched_at": now_iso,
                "status": "unknown",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            channels.append(ch)
    else:
        for r in channels:
            if isinstance(r, dict) and r.get("youtube_channel_id") == youtube_channel_id:
                ch = r
                break
        if not ch:
            ch = {
                "id": _new_id("ytchn"),
                "youtube_channel_id": youtube_channel_id,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now_iso,
                "status": "unknown",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            channels.append(ch)

    # list from cache + pagination
    chan_pls = [p for p in playlists if isinstance(p, dict) and p.get("channel_id") == ch.get("id") and p.get("status") != "deleted"]
    chan_pls.sort(key=lambda r: (r.get("published_at") or ""), reverse=True)

    start = 0
    token_payload = _b64_json_load(page_token) if page_token else None
    if isinstance(token_payload, dict) and token_payload.get("tool") == "get_playlists" and token_payload.get("channel_id") == ch.get("id"):
        try:
            start = int(token_payload.get("offset", 0))
            if start < 0:
                start = 0
        except Exception:
            start = 0
    else:
        start = 0

    page = chan_pls[start:start + req_limit]
    next_offset = start + len(page)
    next_token = None
    if next_offset < len(chan_pls):
        next_token = _b64_json({"tool": "get_playlists", "channel_id": ch.get("id"), "offset": next_offset})

    returned_ids = []
    for p in page:
        p["fetched_at"] = now_iso
        p["updated_at"] = now_iso
        if isinstance(p.get("youtube_playlist_id"), str):
            returned_ids.append(p.get("youtube_playlist_id"))

    op_row["status"] = "succeeded"
    op_row["http_status"] = 200
    op_row["response_body"] = _sanitize({
        "items": [{"youtube_playlist_id": p.get("youtube_playlist_id")} for p in page if isinstance(p, dict)],
        "total_cached_for_channel": len(chan_pls)
    })
    op_row["page_token_out"] = next_token
    op_row["result_playlist_ids"] = returned_ids
    op_row["result_channel_ids"] = [ch.get("youtube_channel_id")] if isinstance(ch.get("youtube_channel_id"), str) else []
    op_row["finished_at"] = now_iso
    op_row["updated_at"] = now_iso
    op_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))

    acct["quota_daily_used_units"] = qused_i + int(op_row["quota_units_charged"])
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso

    _save("playlists.json", playlists)
    _save("channels.json", channels)
    _save("accounts.json", accounts)
    _save("api_operations.json", api_ops)

    return {
        "items": page,
        "channel": ch,
        "page_token": next_token,
        "limit": req_limit,
        "total_cached": len(chan_pls),
        "has_more": bool(next_token),
        "api_operation": op_row
    }

def create_playlist(account_id, title, youtube_channel_id=None, description=None, privacy_status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))

    def _sanitize_params(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize_params(v)
            return out
        if isinstance(obj, list):
            return [_sanitize_params(x) for x in obj]
        return obj

    def _op_log(api_ops, row):
        api_ops.append(row)
        _save("api_operations.json", api_ops)

    def _finalize_op(api_ops, op_row, status_val, http_status=None, error_code=None, error_message=None, response_body=None, result_playlist_ids=None, result_channel_ids=None):
        op_row["status"] = status_val
        op_row["updated_at"] = now_iso
        if op_row.get("started_at") and status_val in ("succeeded", "failed", "cancelled"):
            op_row["finished_at"] = now_iso
        if http_status is not None:
            op_row["http_status"] = int(http_status)
        op_row["error_code"] = error_code
        op_row["error_message"] = error_message
        if response_body is not None:
            op_row["response_body"] = _sanitize_params(response_body)
        if result_playlist_ids is not None:
            op_row["result_playlist_ids"] = result_playlist_ids
        if result_channel_ids is not None:
            op_row["result_channel_ids"] = result_channel_ids
        _save("api_operations.json", api_ops)

    # --- validate inputs ---
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id must match ^ytacct_[0-9A-Z]{18,}$")
    if not isinstance(title, str) or not title:
        return _err("VALIDATION_ERROR", "title must be a non-empty string")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string")
    if youtube_channel_id is not None and (not isinstance(youtube_channel_id, str) or not youtube_channel_id):
        return _err("VALIDATION_ERROR", "youtube_channel_id must be a non-empty string")
    if privacy_status is None:
        privacy_status = "private"
    if privacy_status not in ("public", "private", "unlisted"):
        return _err("VALIDATION_ERROR", "privacy_status must be one of public, private, unlisted")

    # --- load datastore ---
    accounts = _load("accounts.json")
    channels = _load("channels.json")
    playlists = _load("playlists.json")
    api_ops = _load("api_operations.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)

    op_row = {
        "id": _new_id("ytop_"),
        "account_id": account_id if acct else None,
        "tool_name": "create_playlist",
        "youtube_endpoint": "playlists.insert",
        "request_params": _sanitize_params({
            "account_id": account_id,
            "youtube_channel_id": youtube_channel_id,
            "title": title,
            "description": description,
            "privacy_status": privacy_status
        }) or {},
        "request_body": _sanitize_params({
            "snippet": {"title": title, "description": description},
            "status": {"privacy_status": privacy_status}
        }),
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 50,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": None,
        "result_channel_ids": None,
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    _op_log(api_ops, op_row)

    if acct is None:
        _finalize_op(api_ops, op_row, "failed", http_status=401, error_code="authError", error_message="Account not found")
        return _err("UNAUTHORIZED", "Account not found")
    if acct.get("status") != "active":
        _finalize_op(api_ops, op_row, "failed", http_status=401, error_code="authError", error_message="Account not active")
        return _err("UNAUTHORIZED", "Account not active")

    # quota reset if past reset_at
    reset_at = _parse_rfc3339(acct.get("quota_reset_at")) if isinstance(acct.get("quota_reset_at"), str) else None
    if reset_at is None:
        reset_at = now + datetime.timedelta(days=1)
        acct["quota_reset_at"] = reset_at.isoformat() + "Z"
    if now >= reset_at:
        acct["quota_daily_used_units"] = 0
        acct["quota_reset_at"] = (now + datetime.timedelta(days=1)).isoformat() + "Z"

    limit_units = int(acct.get("quota_daily_limit_units") or 0)
    used_units = int(acct.get("quota_daily_used_units") or 0)

    # transition to running
    op_row["status"] = "running"
    op_row["started_at"] = now_iso
    op_row["updated_at"] = now_iso
    _save("api_operations.json", api_ops)

    if limit_units > 0 and used_units + op_row["quota_units_charged"] > limit_units:
        _finalize_op(api_ops, op_row, "failed", http_status=403, error_code="quotaExceeded", error_message="Quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", error_code="quotaExceeded")

    # Determine target channel id: explicit or account default_channel_id (youtube channel id)
    target_ycid = youtube_channel_id or acct.get("default_channel_id")
    if not target_ycid or not isinstance(target_ycid, str):
        _finalize_op(api_ops, op_row, "failed", http_status=400, error_code="invalidArgument", error_message="No target youtube_channel_id available for account")
        return _err("VALIDATION_ERROR", "No target youtube_channel_id available (provide youtube_channel_id or set account default_channel_id)")

    # upsert channel
    ch = next((c for c in channels if c.get("youtube_channel_id") == target_ycid), None)
    if ch is None:
        ch = {
            "id": _new_id("ytchn_"),
            "youtube_channel_id": target_ycid,
            "title": None,
            "description": None,
            "custom_url": None,
            "published_at": None,
            "country": None,
            "subscriber_count": None,
            "video_count": None,
            "view_count": None,
            "etag": None,
            "fetched_at": now_iso,
            "status": "unknown",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        channels.append(ch)
    else:
        ch["fetched_at"] = now_iso
        ch["updated_at"] = now_iso
    _save("channels.json", channels)

    # create playlist (simulate YouTube id)
    yplid = "PL" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:20]
    # enforce unique(youtube_playlist_id)
    if any(p.get("youtube_playlist_id") == yplid for p in playlists):
        # extremely unlikely; regenerate once
        yplid = "PL" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:20]

    prow = {
        "id": _new_id("ytpl_"),
        "youtube_playlist_id": yplid,
        "channel_id": ch["id"],
        "title": title,
        "description": description,
        "privacy_status": privacy_status,
        "item_count": 0,
        "published_at": now_iso,
        "etag": None,
        "fetched_at": now_iso,
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso
    }
    playlists.append(prow)
    _save("playlists.json", playlists)

    acct["quota_daily_used_units"] = used_units + op_row["quota_units_charged"]
    acct["last_used_at"] = now_iso
    acct["updated_at"] = now_iso
    _save("accounts.json", accounts)

    op_row["latency_ms"] = int((time.time() - t0) * 1000)
    _save("api_operations.json", api_ops)

    _finalize_op(
        api_ops, op_row, "succeeded", http_status=200,
        response_body={"youtube_playlist_id": yplid, "playlist_id": prow["id"], "channel_id": ch["id"]},
        result_playlist_ids=[yplid],
        result_channel_ids=[target_ycid]
    )
    return {
        "operation_id": op_row["id"],
        "youtube_endpoint": op_row["youtube_endpoint"],
        "quota_units_charged": op_row["quota_units_charged"],
        "data": {"playlist": prow, "channel": ch}
    }

def get_unpublished_videos(account_id, channel_id=None, youtube_channel_id=None, privacy_status=None, include_scheduled=None, published_before=None, published_after=None, limit=None, page_token=None, order=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # ---- helpers
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        try:
            # accept Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _gen_id(prefix):
        h = hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:22]}"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None, None
        if not isinstance(tok, str) or tok == "":
            return None, _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "page_token is invalid")

    def _sanitize_video(v):
        # return existing row shape (no secrets exist in videos), safe to return as-is copy
        out = dict(v)
        return out

    def _record_op(api_ops, op_row):
        api_ops.append(op_row)
        _save("api_operations.json", api_ops)

    def _update_account(accounts, acct, **updates):
        for k, v in updates.items():
            acct[k] = v
        acct["updated_at"] = _iso(now)
        _save("accounts.json", accounts)

    # ---- validate inputs
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is required and must match ^ytacct_[0-9A-Z]{18,}$")

    if channel_id is not None:
        if not isinstance(channel_id, str) or not re.match(r"^ytchn_[0-9A-Z]{18,}$", channel_id):
            return _err("VALIDATION_ERROR", "channel_id must match ^ytchn_[0-9A-Z]{18,}$ when provided")
    if youtube_channel_id is not None:
        if not isinstance(youtube_channel_id, str) or youtube_channel_id == "":
            return _err("VALIDATION_ERROR", "youtube_channel_id must be a non-empty string when provided")

    if privacy_status is not None:
        if not isinstance(privacy_status, list) or len(privacy_status) < 1:
            return _err("VALIDATION_ERROR", "privacy_status must be an array with at least 1 item when provided")
        allowed_ps = {"private", "unlisted"}
        for it in privacy_status:
            if not isinstance(it, str) or it not in allowed_ps:
                return _err("VALIDATION_ERROR", "privacy_status items must be 'private' or 'unlisted'")
        privacy_status = list(dict.fromkeys(privacy_status))
    if include_scheduled is not None and not isinstance(include_scheduled, bool):
        return _err("VALIDATION_ERROR", "include_scheduled must be a boolean when provided")

    published_before_dt, e = _parse_dt(published_before, "published_before")
    if e: return e
    published_after_dt, e = _parse_dt(published_after, "published_after")
    if e: return e
    if published_before_dt and published_after_dt and published_after_dt > published_before_dt:
        return _err("VALIDATION_ERROR", "published_after must be <= published_before")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

    if order is not None:
        if not isinstance(order, str) or order not in ["date", "rating", "relevance", "title", "videoCount", "viewCount"]:
            return _err("VALIDATION_ERROR", "order must be one of: date, rating, relevance, title, videoCount, viewCount")

    cursor, e = _decode_cursor(page_token)
    if e: return e
    cursor_offset = 0
    if cursor is not None:
        if not isinstance(cursor, dict) or cursor.get("tool") != "get_unpublished_videos":
            return _err("VALIDATION_ERROR", "page_token is not valid for this operation")
        if cursor.get("account_id") != account_id:
            return _err("VALIDATION_ERROR", "page_token does not match account_id")
        try:
            cursor_offset = int(cursor.get("offset", 0))
            if cursor_offset < 0:
                raise ValueError()
        except Exception:
            return _err("VALIDATION_ERROR", "page_token offset is invalid")

    # ---- load store
    accounts = _load("accounts.json")
    channels = _load("channels.json")
    videos = _load("videos.json")
    api_ops = _load("api_operations.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _err("NOT_FOUND", "account not found", account_id=account_id)
    if acct.get("status") != "active":
        # Authenticated tool requires active account
        return _err("UNAUTHORIZED", "account is not active", account_status=acct.get("status"))

    # Quota charging model (server-defined estimate)
    quota_units = 3

    # Create op row (queued)
    op_id = _gen_id("ytop")
    op_row = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "get_unpublished_videos",
        "youtube_endpoint": "search.list",
        "request_params": {
            "account_id": account_id,
            "channel_id": channel_id,
            "youtube_channel_id": youtube_channel_id,
            "privacy_status": privacy_status,
            "include_scheduled": include_scheduled,
            "published_before": published_before,
            "published_after": published_after,
            "limit": limit,
            "page_token": page_token,
            "order": order
        },
        "request_body": None,
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": quota_units,
        "latency_ms": None,
        "page_token_in": page_token,
        "page_token_out": None,
        "result_video_ids": [],
        "result_channel_ids": [],
        "result_playlist_ids": [],
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now)
    }
    _record_op(api_ops, op_row)

    # Transition queued -> running
    op_row["status"] = "running"
    op_row["started_at"] = _iso(now)
    op_row["updated_at"] = _iso(now)
    _save("api_operations.json", api_ops)

    # Enforce quota
    try:
        qlim = int(acct.get("quota_daily_limit_units", 0))
        qused = int(acct.get("quota_daily_used_units", 0))
    except Exception:
        # bad stored data
        op_row["status"] = "failed"
        op_row["finished_at"] = _iso(now)
        op_row["error_code"] = "invalidAccountState"
        op_row["error_message"] = "Account quota counters are invalid"
        op_row["http_status"] = 500
        op_row["updated_at"] = _iso(now)
        op_row["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("CONFLICT", "Account quota counters are invalid")

    if qlim > 0 and (qused + quota_units) > qlim:
        op_row["status"] = "failed"
        op_row["finished_at"] = _iso(now)
        op_row["error_code"] = "quotaExceeded"
        op_row["error_message"] = "Daily quota exceeded"
        op_row["http_status"] = 403
        op_row["updated_at"] = _iso(now)
        op_row["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Resolve channel scope: must be within account default_channel_id (natural UC...) or explicitly associated
    acct_uc = acct.get("default_channel_id")
    if acct_uc is None or not isinstance(acct_uc, str) or acct_uc == "":
        op_row["status"] = "failed"
        op_row["finished_at"] = _iso(now)
        op_row["error_code"] = "invalidArgument"
        op_row["error_message"] = "Account has no default_channel_id"
        op_row["http_status"] = 400
        op_row["updated_at"] = _iso(now)
        op_row["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("CONFLICT", "Account has no default channel configured")

    # Determine requested channel UC id
    requested_uc = None
    requested_channel_row = None
    if channel_id is not None:
        requested_channel_row = next((c for c in channels if c.get("id") == channel_id), None)
        if not requested_channel_row:
            op_row["status"] = "failed"
            op_row["finished_at"] = _iso(now)
            op_row["error_code"] = "notFound"
            op_row["error_message"] = "channel_id not found"
            op_row["http_status"] = 404
            op_row["updated_at"] = _iso(now)
            op_row["latency_ms"] = int((time.time() - t0) * 1000)
            _save("api_operations.json", api_ops)
            return _err("NOT_FOUND", "channel not found", channel_id=channel_id)
        requested_uc = requested_channel_row.get("youtube_channel_id")
    elif youtube_channel_id is not None:
        requested_uc = youtube_channel_id
        requested_channel_row = next((c for c in channels if c.get("youtube_channel_id") == requested_uc), None)
        # if not found, create stub channel (unknown -> active/unknown; keep unknown)
        if not requested_channel_row:
            ch_id = _gen_id("ytchn")
            requested_channel_row = {
                "id": ch_id,
                "youtube_channel_id": requested_uc,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": _iso(now),
                "status": "unknown",
                "created_at": _iso(now),
                "updated_at": _iso(now)
            }
            channels.append(requested_channel_row)
            _save("channels.json", channels)
    else:
        requested_uc = acct_uc
        requested_channel_row = next((c for c in channels if c.get("youtube_channel_id") == requested_uc), None)
        if not requested_channel_row:
            ch_id = _gen_id("ytchn")
            requested_channel_row = {
                "id": ch_id,
                "youtube_channel_id": requested_uc,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": _iso(now),
                "status": "unknown",
                "created_at": _iso(now),
                "updated_at": _iso(now)
            }
            channels.append(requested_channel_row)
            _save("channels.json", channels)

    # Scope enforcement: must match account default channel
    if requested_uc != acct_uc:
        op_row["status"] = "failed"
        op_row["finished_at"] = _iso(now)
        op_row["error_code"] = "authError"
        op_row["error_message"] = "Requested channel is not authorized for this account"
        op_row["http_status"] = 403
        op_row["updated_at"] = _iso(now)
        op_row["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("UNAUTHORIZED", "Not authorized for requested channel")

    # Apply filters over cached videos
    ch_internal_id = requested_channel_row.get("id")
    filtered = []
    for v in videos:
        if v.get("channel_id") != ch_internal_id:
            continue
        # unpublished filter:
        ps = v.get("privacy_status")
        sched = v.get("publish_at")
        is_scheduled = sched is not None
        unpublished_ok = (ps in ("private", "unlisted")) or is_scheduled
        if not unpublished_ok:
            continue

        if privacy_status is not None:
            # scheduled videos included only if include_scheduled True OR they also match privacy_status
            if is_scheduled:
                if include_scheduled is True:
                    pass
                else:
                    # if not including scheduled, allow only if privacy matches filter
                    if ps not in privacy_status:
                        continue
            else:
                if ps not in privacy_status:
                    continue
        else:
            # no privacy_status filter: still may exclude scheduled based on include_scheduled flag
            if is_scheduled and include_scheduled is False:
                continue

        # published_at range filters (if published_at missing, treat as not matching range constraints)
        pub = v.get("published_at")
        pub_dt = None
        if isinstance(pub, str):
            pub_dt, _ = _parse_dt(pub, "published_at")
        if published_before_dt is not None:
            if pub_dt is None or pub_dt >= published_before_dt:
                continue
        if published_after_dt is not None:
            if pub_dt is None or pub_dt <= published_after_dt:
                continue

        filtered.append(v)

    # Sorting (approximation for cached data)
    def _key_date(v):
        # prefer published_at then fetched_at then created_at
        for k in ("published_at", "publish_at", "fetched_at", "created_at"):
            val = v.get(k)
            dt, _ = _parse_dt(val, k) if isinstance(val, str) else (None, None)
            if dt is not None:
                return dt
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if order in (None, "date", "relevance", "rating"):
        filtered.sort(key=_key_date, reverse=True)
    elif order == "title":
        filtered.sort(key=lambda v: (v.get("title") or "").lower())
    elif order == "viewCount":
        filtered.sort(key=lambda v: (v.get("view_count") if isinstance(v.get("view_count"), int) else -1), reverse=True)
    elif order in ("videoCount",):
        # not meaningful per video; fall back
        filtered.sort(key=_key_date, reverse=True)

    total = len(filtered)
    page = filtered[cursor_offset: cursor_offset + limit]
    next_offset = cursor_offset + len(page)
    has_more = next_offset < total
    next_token = _encode_cursor({"tool": "get_unpublished_videos", "account_id": account_id, "offset": next_offset}) if has_more else None

    # Charge quota + update last_used_at
    _update_account(accounts, acct,
                    quota_daily_used_units=(qused + quota_units),
                    last_used_at=_iso(now))

    # Finalize op
    op_row["status"] = "succeeded"
    op_row["finished_at"] = _iso(now)
    op_row["http_status"] = 200
    op_row["page_token_out"] = next_token
    op_row["result_channel_ids"] = [requested_uc] if requested_uc else []
    op_row["result_video_ids"] = [v.get("youtube_video_id") for v in page if v.get("youtube_video_id") is not None]
    op_row["response_body"] = {
        "total": total,
        "returned": len(page),
        "has_more": has_more
    }
    op_row["updated_at"] = _iso(now)
    op_row["latency_ms"] = int((time.time() - t0) * 1000)
    _save("api_operations.json", api_ops)

    return {
        "videos": [_sanitize_video(v) for v in page],
        "channel": {"id": requested_channel_row.get("id"), "youtube_channel_id": requested_uc},
        "page": {"total": total, "limit": limit, "has_more": has_more, "next_page_token": next_token}
    }

def get_current_identity(api_key, account_id=None, **_extra):
    import json, os, datetime, time, hashlib, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _gen_id(prefix):
        h = hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:22]}"

    def _safe_account(a):
        if a is None:
            return None
        out = {k: v for k, v in a.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}
        return out

    # Validate
    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if account_id is not None:
        if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
            return _err("VALIDATION_ERROR", "account_id must match ^ytacct_[0-9A-Z]{18,}$ when provided")

    # Authenticate: no credential collection in schema; treat api_key as an entitlement to use proxy iff store has at least one account.
    accounts = _load("accounts.json")
    api_ops = _load("api_operations.json")

    op_id = _gen_id("ytop")
    op_row = {
        "id": op_id,
        "account_id": None,
        "tool_name": "get_channel_info",  # will correct below; tool_name is constrained but this tool isn't in enum, so we cannot store it there.
        "youtube_endpoint": None,
        "request_params": {"api_key": "***", "account_id": account_id},
        "request_body": None,
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 0,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": [],
        "result_channel_ids": [],
        "result_playlist_ids": [],
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now)
    }

    # Due to api_operations.tool_name enum not including get_current_identity, we must not write an invalid row.
    # Observable dynamics requirement still applies; we will only log to api_operations if we can do so legally.
    # If cannot, return an explicit conflict error rather than corrupting store.
    allowed_tool_names = {"search_videos", "get_video_details", "get_channel_info", "list_channel_videos", "upload_video", "update_video", "get_playlists", "create_playlist", "get_unpublished_videos"}
    if "get_current_identity" not in allowed_tool_names:
        # Enforce authentication/entitlement without logging.
        if len(accounts) == 0:
            return _err("UNAUTHORIZED", "Invalid credential or not entitled to use API proxy")
        # Resolve account context
        resolved = None
        if account_id is not None:
            resolved = next((a for a in accounts if a.get("id") == account_id), None)
            if resolved is None:
                return _err("NOT_FOUND", "account not found", account_id=account_id)
        else:
            # pick any account as visible; prefer active
            resolved = next((a for a in accounts if a.get("status") == "active"), None) or (accounts[0] if accounts else None)

        # Identity response
        return {
            "credential": {"type": "api_key", "api_key_last4": api_key[-4:] if len(api_key) >= 4 else api_key},
            "account": _safe_account(resolved),
            "scopes": resolved.get("scopes") if resolved else [],
            "quota": {
                "daily_limit_units": resolved.get("quota_daily_limit_units") if resolved else None,
                "daily_used_units": resolved.get("quota_daily_used_units") if resolved else None,
                "reset_at": resolved.get("quota_reset_at") if resolved else None
            },
            "rate_limit": None
        }

    # Unreachable given schema; kept for completeness
    return _err("CONFLICT", "Server schema does not allow logging get_current_identity")

def list_accounts(api_key, status=None, provider=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    def _safe_account(a):
        return {k: v for k, v in a.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None, None
        if not isinstance(tok, str) or tok == "":
            return None, _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
        try:
            pad = "=" * (-len(tok) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "page_token is invalid")

    # Validate
    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if status is not None and status not in ("active", "revoked", "suspended"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, suspended")
    if provider is not None and provider != "google":
        return _err("VALIDATION_ERROR", "provider must be 'google' when provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    cursor, e = _decode_cursor(page_token)
    if e: return e
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, dict) or cursor.get("tool") != "list_accounts":
            return _err("VALIDATION_ERROR", "page_token is not valid for this operation")
        try:
            offset = int(cursor.get("offset", 0))
            if offset < 0:
                raise ValueError()
        except Exception:
            return _err("VALIDATION_ERROR", "page_token offset is invalid")

    accounts = _load("accounts.json")

    # Authenticate/entitlement: schema has no api_keys collection, so accept only if there is at least one account provisioned.
    if len(accounts) == 0:
        return _err("UNAUTHORIZED", "Invalid credential or not entitled to use API proxy")

    rows = accounts
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if provider is not None:
        rows = [a for a in rows if a.get("provider") == provider]

    rows.sort(key=lambda a: (a.get("created_at") or "", a.get("id") or ""))
    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = _encode_cursor({"tool": "list_accounts", "offset": next_offset}) if has_more else None

    return {
        "accounts": [_safe_account(a) for a in page],
        "page": {"total": total, "limit": limit, "has_more": has_more, "next_page_token": next_token}
    }

def create_account(api_key, provider, authorization_code, redirect_uri, requested_scopes=None, default_channel_id=None, **_extra):
    import json, os, datetime, time, re, secrets, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize(v)
            return out
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj]
        return obj

    def _safe_account(a):
        if not isinstance(a, dict):
            return a
        return {k: v for k, v in a.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}

    # Validate inputs (RELAX URI validation: accept any non-empty string per real-world server compatibility)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if provider != "google":
        return _err("VALIDATION_ERROR", "provider must be 'google'")
    if not isinstance(authorization_code, str) or not authorization_code.strip():
        return _err("VALIDATION_ERROR", "authorization_code must be a non-empty string")
    if not isinstance(redirect_uri, str) or not redirect_uri.strip():
        # Do not require a well-formed URI here; only that it was provided.
        return _err("VALIDATION_ERROR", "redirect_uri must be a non-empty string")

    if requested_scopes is not None:
        if not isinstance(requested_scopes, list) or len(requested_scopes) < 1:
            return _err("VALIDATION_ERROR", "requested_scopes must be a non-empty array when provided")
        for s in requested_scopes:
            if not isinstance(s, str) or not s.strip():
                return _err("VALIDATION_ERROR", "requested_scopes items must be non-empty strings")

    if default_channel_id is not None and (not isinstance(default_channel_id, str) or not default_channel_id.strip()):
        return _err("VALIDATION_ERROR", "default_channel_id must be a non-empty string when provided")

    # Authenticate api_key (ambient credential store; dataset may use account ids as keys)
    accounts = _load("accounts.json")
    channels = _load("channels.json")
    api_ops = _load("api_operations.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(channels, list):
        channels = []
    if not isinstance(api_ops, list):
        api_ops = []

    authed = False
    for fname in ("api_keys.json", "keys.json", "credentials.json"):
        rows = _load(fname)
        if isinstance(rows, list):
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for k in ("api_key", "key", "value", "token", "secret", "id"):
                    if isinstance(r.get(k), str) and r.get(k) == api_key:
                        authed = True
                        break
                if authed:
                    break
        if authed:
            break
    if not authed:
        # allow account-id-as-key in this datastore
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == api_key and a.get("status") == "active":
                authed = True
                break
    if not authed:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Record api operation: queued->running->(succeeded|failed)
    op_id = _new_id("ytop")
    op = {
        "id": op_id,
        "account_id": None,
        "tool_name": "create_account",
        "youtube_endpoint": "oauth.token",
        "request_params": _sanitize({
            "provider": provider,
            "authorization_code": authorization_code,
            "redirect_uri": redirect_uri,
            "requested_scopes": requested_scopes,
            "default_channel_id": default_channel_id,
        }),
        "request_body": None,
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 0,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": None,
        "result_channel_ids": None,
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_ops.append(op)
    _save("api_operations.json", api_ops)
    op["status"] = "running"
    op["started_at"] = now_iso
    op["updated_at"] = now_iso
    _save("api_operations.json", api_ops)

    # Offline: treat authorization_code as correlator to an existing account when it matches, else create new.
    existing = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == authorization_code:
            existing = a
            break
    if existing and existing.get("status") == "revoked":
        op["status"] = "failed"
        op["finished_at"] = now_iso
        op["updated_at"] = now_iso
        op["http_status"] = 409
        op["error_code"] = "authError"
        op["error_message"] = "Account is revoked and cannot be re-linked (business rule)."
        op["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("CONFLICT", "Account is revoked and cannot be re-linked", operation_id=op_id)

    if existing:
        # idempotent: update settings/scopes if provided; do not store raw tokens
        if requested_scopes is not None:
            existing["scopes"] = list(requested_scopes)
        if default_channel_id is not None:
            existing["default_channel_id"] = default_channel_id
        existing["updated_at"] = now_iso
        existing["last_used_at"] = now_iso
        created = existing
        created_new = False
    else:
        # Ensure unique(provider, google_subject). Offline: synthesize google_subject from authorization_code.
        google_subject = "sub_" + re.sub(r"[^0-9A-Za-z]+", "", authorization_code)[:40]
        for a in accounts:
            if isinstance(a, dict) and a.get("provider") == provider and a.get("google_subject") == google_subject:
                # if active/suspended we allow idempotent "return existing"
                if a.get("status") in ("active", "suspended"):
                    created = a
                    created_new = False
                    break
                return _err("CONFLICT", "Google subject is already connected and cannot be re-linked", rule="unique(provider, google_subject)")
        else:
            created = None
            created_new = True

        if created is None:
            # resolve/create default channel if given
            if default_channel_id is not None:
                # ensure channels has row with this youtube_channel_id
                ch = None
                for c in channels:
                    if isinstance(c, dict) and c.get("youtube_channel_id") == default_channel_id:
                        ch = c
                        break
                if ch is None:
                    ch = {
                        "id": _new_id("ytchn"),
                        "youtube_channel_id": default_channel_id,
                        "title": None,
                        "description": None,
                        "custom_url": None,
                        "published_at": None,
                        "country": None,
                        "subscriber_count": None,
                        "video_count": None,
                        "view_count": None,
                        "etag": None,
                        "fetched_at": now_iso,
                        "status": "unknown",
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    channels.append(ch)
                    _save("channels.json", channels)

            acct_id = _new_id("ytacct")
            created = {
                "id": acct_id,
                "provider": provider,
                "google_subject": google_subject,
                "default_channel_id": default_channel_id,
                "scopes": list(requested_scopes) if requested_scopes is not None else [],
                "access_token_ciphertext": "enc_" + _new_id("tok"),
                "refresh_token_ciphertext": "enc_" + _new_id("rtok"),
                "token_expires_at": (now_dt + datetime.timedelta(hours=1)).isoformat().replace("+00:00", "Z"),
                "quota_daily_limit_units": 0,
                "quota_daily_used_units": 0,
                "quota_reset_at": (now_dt + datetime.timedelta(days=1)).replace(hour=7, minute=0, second=0).isoformat().replace("+00:00", "Z"),
                "status": "active",
                "last_used_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            accounts.append(created)

    _save("accounts.json", accounts)

    # finalize op
    op["account_id"] = created.get("id")
    op["status"] = "succeeded"
    op["finished_at"] = now_iso
    op["updated_at"] = now_iso
    op["http_status"] = 200 if not created_new else 201
    op["response_body"] = _sanitize({"account_id": created.get("id")})
    op["latency_ms"] = int((time.time() - t0) * 1000)
    _save("api_operations.json", api_ops)

    return {"account": _safe_account(created), "operation_id": op_id}

def update_account(api_key, account_id, default_channel_id=None, quota_daily_limit_units=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    def _safe_account(a):
        if not isinstance(a, dict):
            return a
        return {k: v for k, v in a.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if default_channel_id is not None and (not isinstance(default_channel_id, str) or not default_channel_id.strip()):
        return _err("VALIDATION_ERROR", "default_channel_id must be a non-empty string when provided")
    if quota_daily_limit_units is not None:
        if not isinstance(quota_daily_limit_units, int):
            return _err("VALIDATION_ERROR", "quota_daily_limit_units must be an integer")
        if quota_daily_limit_units < 0:
            return _err("VALIDATION_ERROR", "quota_daily_limit_units must be >= 0")
    if status is not None and status not in ("active", "revoked", "suspended"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, suspended")

    accounts = _load("accounts.json")
    channels = _load("channels.json")
    api_ops = _load("api_operations.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(channels, list):
        channels = []
    if not isinstance(api_ops, list):
        api_ops = []

    # Authenticate api_key
    authed = False
    for fname in ("api_keys.json", "keys.json", "credentials.json"):
        rows = _load(fname)
        if isinstance(rows, list):
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for k in ("api_key", "key", "value", "token", "secret", "id"):
                    if isinstance(r.get(k), str) and r.get(k) == api_key:
                        authed = True
                        break
                if authed:
                    break
        if authed:
            break
    if not authed:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == api_key and a.get("status") == "active":
                authed = True
                break
    if not authed:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Find account
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if not acct:
        return _err("NOT_FOUND", "Account not found")

    # Create api operation (even for settings changes)
    def _new_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    op_id = _new_id("ytop")
    op = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "update_account",
        "youtube_endpoint": None,
        "request_params": {
            "account_id": account_id,
            "default_channel_id": default_channel_id,
            "quota_daily_limit_units": quota_daily_limit_units,
            "status": status,
        },
        "request_body": None,
        "response_body": None,
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 0,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": None,
        "result_channel_ids": None,
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_ops.append(op)
    _save("api_operations.json", api_ops)
    op["status"] = "running"
    op["started_at"] = now_iso
    op["updated_at"] = now_iso
    _save("api_operations.json", api_ops)

    # Apply lifecycle transition if requested
    if status is not None:
        cur = acct.get("status")
        allowed = {
            "active": ("revoked", "suspended"),
            "suspended": ("active", "revoked"),
            "revoked": (),
        }
        if cur not in allowed:
            op["status"] = "failed"
            op["finished_at"] = now_iso
            op["updated_at"] = now_iso
            op["http_status"] = 409
            op["error_code"] = "invalidTransition"
            op["error_message"] = "Current account status is invalid."
            op["latency_ms"] = int((time.time() - t0) * 1000)
            _save("api_operations.json", api_ops)
            return _err("INVALID_TRANSITION", "Current account status is invalid", operation_id=op_id)
        if status != cur and status not in allowed[cur]:
            op["status"] = "failed"
            op["finished_at"] = now_iso
            op["updated_at"] = now_iso
            op["http_status"] = 409
            op["error_code"] = "invalidTransition"
            op["error_message"] = f"Invalid account status transition {cur}->{status}."
            op["latency_ms"] = int((time.time() - t0) * 1000)
            _save("api_operations.json", api_ops)
            return _err("INVALID_TRANSITION", f"Invalid account status transition {cur}->{status}", operation_id=op_id)
        acct["status"] = status

    # Apply quota limit update (enforce constraints)
    if quota_daily_limit_units is not None:
        used = acct.get("quota_daily_used_units")
        try:
            used = int(used) if used is not None else 0
        except Exception:
            used = 0
        if quota_daily_limit_units > 0 and used > quota_daily_limit_units:
            op["status"] = "failed"
            op["finished_at"] = now_iso
            op["updated_at"] = now_iso
            op["http_status"] = 409
            op["error_code"] = "invalidArgument"
            op["error_message"] = "quota_daily_limit_units cannot be set below quota_daily_used_units."
            op["latency_ms"] = int((time.time() - t0) * 1000)
            _save("api_operations.json", api_ops)
            return _err("CONFLICT", "quota_daily_limit_units cannot be set below quota_daily_used_units", rule="quota_daily_used_units <= quota_daily_limit_units OR quota_daily_limit_units = 0", operation_id=op_id)
        acct["quota_daily_limit_units"] = quota_daily_limit_units

    # Apply default channel update: ensure channel cache exists (create stub if needed)
    if default_channel_id is not None:
        acct["default_channel_id"] = default_channel_id
        found = False
        for c in channels:
            if isinstance(c, dict) and c.get("youtube_channel_id") == default_channel_id:
                found = True
                break
        if not found:
            channels.append({
                "id": _new_id("ytchn"),
                "youtube_channel_id": default_channel_id,
                "title": None,
                "description": None,
                "custom_url": None,
                "published_at": None,
                "country": None,
                "subscriber_count": None,
                "video_count": None,
                "view_count": None,
                "etag": None,
                "fetched_at": now_iso,
                "status": "unknown",
                "created_at": now_iso,
                "updated_at": now_iso,
            })

    # Ensure "NO SUCCESS WITHOUT EFFECT"
    if status is None and quota_daily_limit_units is None and default_channel_id is None:
        op["status"] = "failed"
        op["finished_at"] = now_iso
        op["updated_at"] = now_iso
        op["http_status"] = 400
        op["error_code"] = "invalidArgument"
        op["error_message"] = "No mutable fields provided to update."
        op["latency_ms"] = int((time.time() - t0) * 1000)
        _save("api_operations.json", api_ops)
        return _err("VALIDATION_ERROR", "No mutable fields provided to update")

    acct["updated_at"] = now_iso
    _save("channels.json", channels)
    _save("accounts.json", accounts)  # FIX: persist mutation so later reads observe it

    # Finalize op
    op["status"] = "succeeded"
    op["finished_at"] = now_iso
    op["updated_at"] = now_iso
    op["latency_ms"] = int((time.time() - t0) * 1000)
    op["response_body"] = {"account_id": account_id}
    _save("api_operations.json", api_ops)

    return {"account": _safe_account(acct), "operation_id": op_id}

def list_api_operations(api_key, account_id=None, tool_name=None, status=None, started_after=None, started_before=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")
    t0 = time.time()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _sanitize(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk:
                    continue
                out[k] = _sanitize(v)
            return out
        if isinstance(obj, list):
            return [_sanitize(x) for x in obj]
        return obj

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if account_id is not None and (not isinstance(account_id, str) or not re.match(r"^ytacct_[0-9A-Z]{18,}$", account_id)):
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled")

    sa = _parse_rfc3339(started_after) if started_after is not None else None
    if started_after is not None and sa is None:
        return _err("VALIDATION_ERROR", "started_after must be RFC3339 date-time")
    sb = _parse_rfc3339(started_before) if started_before is not None else None
    if started_before is not None and sb is None:
        return _err("VALIDATION_ERROR", "started_before must be RFC3339 date-time")
    if sa and sb and sa > sb:
        return _err("VALIDATION_ERROR", "started_after must be <= started_before")

    if limit is None:
        limit_eff = 50
    else:
        if not isinstance(limit, int) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        limit_eff = 200 if limit > 200 else limit

    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")

    accounts = _load("accounts.json")
    api_ops = _load("api_operations.json")
    if not isinstance(accounts, list): accounts = []
    if not isinstance(api_ops, list): api_ops = []

    # Authenticate api_key: try credential stores; fallback to account-id-as-key.
    authed = False
    for fname in ("api_keys.json", "keys.json", "credentials.json"):
        rows = _load(fname)
        if isinstance(rows, list):
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for k in ("api_key", "key", "value", "token", "secret", "id"):
                    if isinstance(r.get(k), str) and r.get(k) == api_key:
                        authed = True
                        break
                if authed:
                    break
        if authed:
            break
    if not authed:
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == api_key and a.get("status") == "active":
                authed = True
                break
    if not authed:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Pagination token as base64 offset
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    # Filter
    rows = []
    for op in api_ops:
        if not isinstance(op, dict):
            continue
        if account_id is not None and op.get("account_id") != account_id:
            continue
        if tool_name is not None and op.get("tool_name") != tool_name:
            continue
        if status is not None and op.get("status") != status:
            continue
        if sa is not None:
            odt = _parse_rfc3339(op.get("started_at")) if isinstance(op.get("started_at"), str) else None
            if odt is not None and odt < sa:
                continue
            if odt is None and op.get("started_at") is not None:
                continue
        if sb is not None:
            odt = _parse_rfc3339(op.get("started_at")) if isinstance(op.get("started_at"), str) else None
            if odt is not None and odt > sb:
                continue
            if odt is None and op.get("started_at") is not None:
                continue
        # Ensure no raw tokens leak
        op2 = dict(op)
        op2["request_params"] = _sanitize(op2.get("request_params"))
        op2["request_body"] = _sanitize(op2.get("request_body"))
        op2["response_body"] = _sanitize(op2.get("response_body"))
        rows.append(op2)

    # Sort newest first by created_at then started_at
    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("started_at") or ""), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit_eff]
    next_offset = offset + limit_eff
    has_more = next_offset < total
    next_page_token = None
    if has_more:
        next_page_token = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "operations": page,
        "limit": limit_eff,
        "total": total,
        "has_more": has_more,
        "page_token": next_page_token,
        "latency_ms": latency_ms
    }

def cancel_api_operation(api_key, api_operation_id, reason=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0010000" if __import__("os").path.isdir("./environment_mix/0010000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(22))

    def _ms_since(t_start):
        return int(round((time.time() - t_start) * 1000))

    def _sanitize_reason(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if len(s2) > 500:
            s2 = s2[:500]
        return s2

    # ---- Validate inputs (strict to parameter schema, but do not enforce pattern as a hard business rule) ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(api_operation_id, str) or not api_operation_id.strip():
        return _err("VALIDATION_ERROR", "api_operation_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")
    if isinstance(reason, str) and len(reason) > 500:
        return _err("VALIDATION_ERROR", "reason must be at most 500 characters")
    reason_s = _sanitize_reason(reason)

    # ---- Load datastore ----
    accounts = _load("accounts.json")
    ops = _load("api_operations.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(ops, list):
        ops = []

    # ---- Resolve authentication context ----
    # Credential is a server-issued api_key; in this datastore it is represented by accounts.id (client-visible).
    authed = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == api_key:
            authed = a
            break
    if not authed:
        return _err("UNAUTHORIZED", "Invalid api_key")
    if authed.get("status") != "active":
        return _err("UNAUTHORIZED", "Account is not active")

    # ---- Create an operation log row for this tool invocation (queued->running->succeeded|failed) ----
    op_row = {
        "id": _new_id("ytop"),
        "account_id": authed.get("id"),
        "tool_name": "cancel_api_operation",
        "youtube_endpoint": None,
        "request_params": {"api_operation_id": api_operation_id, "reason": reason_s},
        "request_body": None,
        "response_body": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "quota_units_charged": 0,
        "latency_ms": None,
        "page_token_in": None,
        "page_token_out": None,
        "result_video_ids": None,
        "result_channel_ids": None,
        "result_playlist_ids": None,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    ops.append(op_row)
    _save("api_operations.json", ops)

    # Transition to running
    op_row["status"] = "running"
    op_row["started_at"] = now_iso
    op_row["updated_at"] = now_iso
    _save("api_operations.json", ops)

    def _finish(status, response_body=None, error_code=None, error_message=None, http_status=None):
        finished_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        op_row["status"] = status
        op_row["finished_at"] = finished_iso
        op_row["updated_at"] = finished_iso
        op_row["latency_ms"] = _ms_since(t0)
        op_row["response_body"] = response_body
        op_row["error_code"] = error_code
        op_row["error_message"] = error_message
        op_row["http_status"] = http_status
        _save("api_operations.json", ops)

    # ---- Find target operation ----
    target = None
    for r in ops:
        if isinstance(r, dict) and r.get("id") == api_operation_id:
            target = r
            break
    if not target:
        _finish(
            "failed",
            response_body=None,
            error_code="notFound",
            error_message="Target api_operation_id does not exist.",
            http_status=404,
        )
        return _err("NOT_FOUND", "api_operation_id not found")

    # ---- Ownership check (business rule) ----
    if target.get("account_id") != authed.get("id"):
        _finish(
            "failed",
            response_body=None,
            error_code="authError",
            error_message="Operation not owned by the authenticated account.",
            http_status=403,
        )
        return _err("UNAUTHORIZED", "Operation not owned by the caller")

    # ---- State transition rules ----
    current = target.get("status")
    if current in ("succeeded", "failed", "cancelled"):
        _finish(
            "failed",
            response_body=None,
            error_code="invalidArgument",
            error_message="Refuses cancellation of terminal operations (succeeded/failed/cancelled).",
            http_status=409,
        )
        return _err("INVALID_TRANSITION", "Cannot cancel a terminal operation", from_status=current, to_status="cancelled")

    if current not in ("queued", "running"):
        _finish(
            "failed",
            response_body=None,
            error_code="invalidArgument",
            error_message="Operation is not in a cancellable state (queued or running).",
            http_status=409,
        )
        return _err("INVALID_TRANSITION", "Operation is not in a cancellable state", from_status=current, to_status="cancelled")

    # Perform cancellation (queued->cancelled or running->cancelled)
    target["status"] = "cancelled"
    # Ensure lifecycle constraints: if cancelled then finished_at and started_at must be set.
    if not target.get("started_at"):
        target["started_at"] = now_iso
    target["finished_at"] = now_iso
    target["updated_at"] = now_iso

    # Record reason in a sanitized way without storing secrets; use response_body as an internal note
    if reason_s:
        rb = target.get("response_body")
        if not isinstance(rb, dict):
            rb = {}
        rb["cancel_reason"] = reason_s
        target["response_body"] = rb

    # Persist target update
    _save("api_operations.json", ops)

    # Update account last_used_at
    authed["last_used_at"] = now_iso
    authed["updated_at"] = now_iso
    _save("accounts.json", accounts)

    # Finish invocation op as succeeded
    _finish(
        "succeeded",
        response_body={"cancelled_operation_id": target.get("id"), "new_status": "cancelled"},
        error_code=None,
        error_message=None,
        http_status=200,
    )

    return {"operation": target, "meta": {"cancel_invocation_operation_id": op_row["id"]}}
